(window.MATRIX_DATA_PARTS ||= Object.create(null))["data/glyphs-0015.js"] = [{"id":"glyph-seal-51d1","script":"seal","character":"凑","reading":"còu","description":"còu：(1)聚合～钱。～数。～合。拼～。紧～。\n(2)接近～近。往前～。\n(3)碰，赶，趁～巧（碰巧）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-凑"},{"id":"glyph-seal-51dd","script":"seal","character":"凝","reading":"níng","description":"níng：(1)气体变为液体或液体变为固体～结。～固。～冻。～集。～脂。～滞。\n(2)聚集，集中～聚。～重（zhòng）。～神（聚精会神）。～思。～眸。～睇（注视）。～练。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-凝"},{"id":"glyph-seal-51e0","script":"seal","character":"几","reading":"jǐ","description":"⒈疑问词。问数量～本书？～点钟？\n⒉〈表〉不定数她才二十～岁。只有～件衣服。\n①多少曾～何时？\n⒋见jī。\n几jì 1.通\"冀\"。期望，希望。 2.通\"纪\"。年岁。\n几qí 1.沂鄂。器物上的凹凸线纹。沂，凹纹;鄂，凸纹。 2.通\"颀\"。身长貌。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-几"},{"id":"glyph-seal-51e1","script":"seal","character":"凡","reading":"fán","description":"fán：(1)平常的，不出奇的平～。～庸。～夫俗子。\n(2)指人世间（宗教或迷信的说法）～尘。～心。\n(3)所有的～年满十八岁的公民，都有选举权与被选举权。～是。\n(4)总共全书～二十八卷。\n(5)大概，要略大～。～例。发～（陈述全书或某一学科的要旨）。\n(6)中国古代乐谱的记音符号，相当于简谱4”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-凡"},{"id":"glyph-seal-51e4","script":"seal","character":"凤","reading":"fèng","description":"古时比喻有圣德的人\n【凤毛麟角】凤凰的毛，麒麟的角。〈喻〉稀罕、珍贵的事物，也指难得的人才。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-凤"},{"id":"glyph-seal-51eb","script":"seal","character":"凫","reading":"fú","description":"动物名。俗名野鸭\n另一说凫是家鸭”\n浮游;泅水\n⒈俗称\"野鸭\"。形状像鸭子，种类很多，但已逐年减少，要保护。常见的是绿头野鸭，雄的头部绿色背部黑褐色，颈下有一白环。雌的全身黑褐色。常群游湖泊中，能飞。现已\n有人工养殖,肉可吃，羽毛可制绒。\n⒉〈方〉同\"洑\"。游泳～水。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-凫"},{"id":"glyph-seal-51ed","script":"seal","character":"凭","reading":"píng","description":"依托;仰仗\n⒈靠着～栏。～窗。\n⒉依靠，仗持，依据全～大家。～仗。～借。～险固守。\n⒊根据～票进场。\n⒋证据～证。～据。真～实据。\n⒌任，随海阔～鱼跃。\n⒍登临～高独苦吟。\n⒎［凭空］没有依据～空捏造。\n⒏［凭吊］面对遗迹、坟墓等表示怀念～吊先烈。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-凭"},{"id":"glyph-seal-51f6","script":"seal","character":"凶","reading":"xiōng","description":"xiōng：(1)不幸的，不吉祥的吉～。～信。\n(2)庄稼收成不好～年饥岁。\n(3)恶～暴。～恶。～顽。～相（xiàng）。～神恶煞。\n(4)关于杀伤的行（xíng）～。帮～。\n(5)厉害，过甚雨～风狂。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-凶"},{"id":"glyph-seal-51fa","script":"seal","character":"出","reading":"chū","description":"引申为出入的出”。出去,出来,与入”相对\n出车彭彭。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-出"},{"id":"glyph-seal-51fb","script":"seal","character":"击","reading":"jī","description":"不肯击缻。\n使击柝如故。\n攻击;攻打\n⒉攻打攻～。拳～。炮～。导弹～。〈引〉击杀～牛。\n⒊刺～剑。\n击xí 1.男巫。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-击"},{"id":"glyph-seal-51fd","script":"seal","character":"函","reading":"hán","description":"hán：(1)匣，盒子石～。剑～。\n(2)套子，引申为量词书～。信一～（信一封）。\n(3)信件～件。公～。来～。\n(4)包含，容纳～夏（夏”，指中国；函夏”即包括整个中国）。巨蚌～珠。\n(5)铠甲～人（制甲的人）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-函"},{"id":"glyph-seal-51ff","script":"seal","character":"凿","reading":"záo","description":"挖掘;开凿\n水凿之处。\n⒈挖槽或打孔用的工具钢～子。\n⒉打孔，挖通～个洞。～渠引水。\n⒊确实证据确～。\n凿zuò 1.鲜明貌。 2.确实。 3.通\"糳\"。舂成精米。 4.指精米。\n凿zú 1.镌刻;雕镂。 2.通\"镞\"。箭头。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-凿"},{"id":"glyph-seal-5200","script":"seal","character":"刀","reading":"dāo","description":"dāo：(1)用来切、割、斩、削、砍、刺、铡的工具～子。～兵。～法。剪～。镰～。\n(2)中国的纸张计量单位一刀合一百张。\n(3)古代的一种钱币，因其形如刀故称～币。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-刀"},{"id":"glyph-seal-5203","script":"seal","character":"刃","reading":"rèn","description":"rèn：(1)刀的锋利部分刀～儿。～口。\n(2)刀利～。白～。\n(3)用刀杀与人～我，宁自～。手～亲仇。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-刃"},{"id":"glyph-seal-5206","script":"seal","character":"分","reading":"fēn；fèn","description":"fēn：(1)区划开～开。划～。～野（划分的范围）。～界。～明。条～缕析。～解。\n(2)由整体中取出或产生出一部分～发。～忧。～心劳神。\n(3)由机构内独立出的部分～会。～行（háng）。\n(4)散，离～裂。～离。～别。～崩离析。～门别类。\n(5)辨别区～。～析。\n(6)区划而成的部分二～之一。\n(7)一半人生百年，昼夜各～。春～。秋～。\n合；总；\nfèn：(1)名位、职责、权利的限度～所当然。身～。～内。恰如其～。安～守己。\n(2)构成事物的不同的物质或因素成～。天～（天资）。情～（情谊）。\n(3)料想自～已死久矣”。\n(4)同份”，属于一定的阶层、集团或具有某种特征的人知识～子。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-分"},{"id":"glyph-seal-5207","script":"seal","character":"切","reading":"qiē；qiè","description":"qiē：用刀从上往下用力～菜。～除。～磋（本义是把骨角玉石加工制成器物，引申为在业务、思想各方面互相吸取长处，纠正缺点，如～～琢磨”）。\nqiè：(1)密合，贴近～当（dàng）。～肤（切身）。～己。亲～。\n(2)紧急急～。迫～。\n(3)实在～忌。恳～。\n(4)旧时汉语标音的一种方法，用两个字，取上一字的声母与下一字的韵母拼成一个音。亦称反切”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-切"},{"id":"glyph-seal-5208","script":"seal","character":"刈","reading":"yì","description":"yì：割（草或谷类）～除。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-刈"},{"id":"glyph-seal-520a","script":"seal","character":"刊","reading":"kān","description":"kān：(1)斫，消除，修改～误（亦作勘误”）。校（jiào）～。不～之论（喻至理名言）。\n(2)刻～石。～印。～本。\n(3)排版印刷～行（xíng）。创～。～登。～载。\n(4)出版物～物。报～。书～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-刊"},{"id":"glyph-seal-520d","script":"seal","character":"刍","reading":"chú","description":"用草喂牲口\n刍 〈名〉\n喂牲畜的草\n民争负\n①喂牲畜用的草～秣。\n②割草。\n【刍议】谦辞。指自己粗浅的意见、议论。\n⒈割草～牧田中。\n⒉牲畜吃的草。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-刍"},{"id":"glyph-seal-520e","script":"seal","character":"刎","reading":"wěn","description":"wěn：抹脖子自～。\n〔～颈之交〕旧称同生死共患难的朋友，如卒相与欢，为～～～～”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-刎"},{"id":"glyph-seal-5211","script":"seal","character":"刑","reading":"xíng","description":"xíng：(1)对犯罪的处罚～罚。～法。～律。～事。执～。服～。\n(2)特指对犯人的体罚～讯。受～。～具。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-刑"},{"id":"glyph-seal-5212","script":"seal","character":"划","reading":"huá","description":"以桨拨水使船前进\n合算\n指二人伸指猜拳行酒。也作豁拳”\n划 〈名〉\n划子,小船\n用尖利物把东西割开\n摩擦;抹拭\n⒈用尖锐的东西把别的物体分割开～玻璃。～西瓜。〈引〉破裂这苹果～了一条口。霹雳闪电～长空。\n⒉擦～火柴。\n⒊拨水前进～水。～船。\n⒋合算，相宜～得来。\n⒈区分～分界限。～清敌我。\n⒉设计，安排计～。筹～。\n⒊拨，分配～拨。～款。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-划"},{"id":"glyph-seal-5216","script":"seal","character":"刖","reading":"yuè","description":"yuè：古代的一种酷刑，把脚砍掉昔卞和献宝，楚王～之”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-刖"},{"id":"glyph-seal-5217","script":"seal","character":"列","reading":"liè","description":"liè：(1)排成一行罗～。行（háng）～。队～。～岛。\n(2)名，众～位。～强。～传（zhuàn）。\n(3)摆出～举。\n(4)安排到某类事务之中～席。\n(5)量词，用于成行列的事物一～火车。\n(6)类不在此～。\n(7)姓。\n(8)古同烈”，强烈，猛然。\n(9)古同裂”，分裂。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-列"},{"id":"glyph-seal-5218","script":"seal","character":"刘","reading":"liú","description":"克,战胜\n兵器名。斧钺","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-刘"},{"id":"glyph-seal-5219","script":"seal","character":"则","reading":"zé","description":"⒈规则，规律，制度准～。法～。总～。细～。\n⒉榜样，模范以身作～。\n⒊效法～先人之法。\n⒋就，便，那么有～改之，无～加勉。唇亡～齿寒。\n⒏连词。用于对比句或两件事先后相承内～百姓疾之，外～诸侯叛之。响了预备铃，～同学们陆续走入教室。\n⒑量词，指成文的条数寓言两～。试题五～。新闻三～。\n⒒在一、二、三等数字后，表示列举事项一～屋少，二～人多，故住房紧张。\n则zhī 1.姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-则"},{"id":"glyph-seal-521a","script":"seal","character":"刚","reading":"gāng","description":"坚强\n子曰刚毅木讷,近仁。\n⒈坚硬，坚定，坚强跟\"柔\"相对～正。～毅。～强。以柔克～。\n⒉副词。才，方才～才。她～走。\n⒊副词。正好，恰好～好。～ ～合适。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-刚"},{"id":"glyph-seal-521b","script":"seal","character":"创","reading":"chuàng","description":"疮疖。皮肤或粘膜上的溃烂处。通疮”\n损伤;伤害\n创 chuāng创伤～痕、重～。又见chuàng。\n【创巨痛深】创伤大，痛苦深。形容遭受严重的损害。\n【创汇】创造外汇收入的缩略语。\n【创见】前人未提出过的新见解。\n【创举】从来不曾有过的举动或事业。\n【创造学】指能够充分开发人的创造力，进而提高工作、学习、生产和科研效率的一门科学。兴起于20世纪中叶。\n【创作冲动】作家、艺术家在生活实践中由于受到某种事物的启发和激励而产生的强烈的创作愿望。又称艺术冲动。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-创"},{"id":"glyph-seal-521d","script":"seal","character":"初","reading":"chū","description":"chū：(1)开始时，开始的部分～始。正月～一。～旬。～稿。～等。～版。～试。～创。～绽。～叶（指某一历史时期的最初一段）。～夜（a.指进入夜晚不久的时候；b.指新婚第一夜）。\n(2)原来的，原来的情况～衷⊥好如～。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-初"},{"id":"glyph-seal-5220","script":"seal","character":"删","reading":"shān","description":"shān：削除文辞中的某些字句～除。～改。～减。～定。～节。～夷（亦作删刈”）。～繁就简。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-删"},{"id":"glyph-seal-5224","script":"seal","character":"判","reading":"pàn","description":"pàn：(1)区别，分辨，断定～明。～辨。～据。～读（利用已知的视觉信息符号来判断新获得的视觉信息的含义）。～断。\n(2)分开，截然不同～然。～若两人。～若鸿沟。\n(3)评定裁～。谈～。～卷子。\n(4)司法机关对案件的裁决～词。～决。～案。\n(5)古代官名通～。～官（中国唐、宋两代辅助地方长官处理公事的人员，传说中借指阎王手下管生死簿的官）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-判"},{"id":"glyph-seal-5229","script":"seal","character":"利","reading":"lì","description":"lì：(1)好处，与害”弊”相对～弊。～害。～益。～令智昏。兴～除弊。\n(2)使顺利、得到好处～己。～用厚生（充分发挥物的作用，使民众生活优厚富裕起来）。\n(3)与愿望相符合吉～。顺～。\n(4)刀口快，针尖锐，与钝”相对～刃。～刀。～剑。～落。～口巧辩。\n(5)从事生产、交易、货款、储蓄所得超过本钱的收获～息。～率（lǜ）。一本万～。\n(6)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-利"},{"id":"glyph-seal-522b","script":"seal","character":"别","reading":"bié","description":"bié：(1)分离～离。～情。～绪（离别时离别后的情感）。分～。告～。久～重逢。分门～类。\n(2)差别霄壤之～。\n(3)分类类～。性～。职～。级～。派～。\n(4)另外的～人。～号。～字。～墅。～论。～开生面。\n(5)卡住，插住，绷住～针。～花。\n(6)不要，不准～动。\n（彆）\nbiè：〔～扭〕不顺心，不相投（扭”读轻声）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-别"},{"id":"glyph-seal-522d","script":"seal","character":"刭","reading":"jǐng","description":"果北乡自刭。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-刭"},{"id":"glyph-seal-522e","script":"seal","character":"刮","reading":"guā","description":"扫拂;刷抹\n⒈使用刀子等去掉物体表面的东西～毛。～铁锈。〈喻〉掠夺，搜取搜～民财。贪官～地皮。\n⒊涂抹～灰浆。\n⒋吹～风。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-刮"},{"id":"glyph-seal-5230","script":"seal","character":"到","reading":"dào","description":"dào：(1)从别处来～达。～站。～来。～场。～任。～职。～案。签～。恰～好处。\n(2)往～群众中去。\n(3)周全，全顾得着周～。面面俱～。\n(4)成功得～。办～。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-到"},{"id":"glyph-seal-5233","script":"seal","character":"刳","reading":"kū","description":"kū：从中间破开再挖空～木为舟。～心（道教指澄清内心的杂念）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-刳"},{"id":"glyph-seal-5236","script":"seal","character":"制","reading":"zhì","description":"制定,用文字规定\n泽上有水,节,君子以制数度,议德行。╠\n⒈规定，拟定～定。～订。因地～宜。\n⒉禁止，限定，约束，管束～止。～约。限～。控～。遏～。管～。\n⒊规章，法度，法则～度。法～。民主集中～。\n⒋造，作～造。～作。～版。～图。\n①用强力使驯服、服从。也作\"制伏\"。\n②按规定样式做的服装学生～服。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-制"},{"id":"glyph-seal-5237","script":"seal","character":"刷","reading":"shuā；shuà","description":"shuā：(1)用成束的毛棕等制成的清除或涂抹的用具～子。毛～。板～。\n(2)擦拭，涂抹，清洗～牙。～墙。～洗。印～。～耻（洗雪耻辱）。\n(3)剔除，淘汰～选（剔除）。～掉。\nshuà：〔～白〕色白而略微发青。\n〔～俐〕形容动作很敏捷。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-刷"},{"id":"glyph-seal-5238","script":"seal","character":"券","reading":"quàn；xuàn","description":"quàn：古代的契据，常分为两半，双方各执其一，现代指票据或作凭证的纸片债～。国库～。入场～。证～。稳操胜～。\nxuàn：〔拱～〕门窗、桥梁等建筑成弧形的部分。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-券"},{"id":"glyph-seal-5239","script":"seal","character":"刹","reading":"shā；chà","description":"chà：梵语刹多罗”的简称，寺庙佛塔古～。宝～。\nshā：止住～车。～住这股歪风。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-刹"},{"id":"glyph-seal-523a","script":"seal","character":"刺","reading":"cì；cī","description":"cì：(1)用有尖的东西插入～绣。～伤。～杀。\n(2)暗杀～客。被～。行～。\n(3)侦探，打听～探。\n(4)用尖锐的话指出别人的坏处讽～。讥～。\n(5)尖锐像针的东西芒～。鱼～。～丛。\ncī：象声词～地滑了一跤。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-刺"},{"id":"glyph-seal-523b","script":"seal","character":"刻","reading":"kè","description":"kè：(1)雕，用刀子挖～本（雕版印成的书本）。～石。～字。～板。～舟求剑。\n(2)古代用漏壶记时，一昼夜共一百刻。今用钟表计时，一刻等于十五分钟五点一～。\n(3)时间此～。即～。顷～（极短时间）。时～。～不容缓。\n(4)形容程度极深深～。～意。～骨（感受深切入骨）。～苦。\n(5)不厚道～毒。～薄。尖～。苛～。\n(6)同克”④。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-刻"},{"id":"glyph-seal-523d","script":"seal","character":"刽","reading":"guì","description":"割断,砍断\n⒈砍断。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-刽"},{"id":"glyph-seal-523f","script":"seal","character":"刿","reading":"guì","description":"割开,切口\n通会”。聚合,汇合","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-刿"},{"id":"glyph-seal-5240","script":"seal","character":"剀","reading":"kǎi","description":"磨,磨刀\n规劝,讽喻\n杀;砍\n中肯,切实\n⒈讽喻，以此喻彼～讽。\n⒉确实，切实～晓大义。\n①切实～切开导。\n②与事理相符合～切中理。～切详明。\n剀ái 1.捱，挨。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-剀"},{"id":"glyph-seal-5242","script":"seal","character":"剂","reading":"jì","description":"调节;调和\n古代买卖时用的契券\n①齐，齐平。\n②剪绝;割截。\n③调和;调节。\n④指以多味药合成的药剂。\n⑤指制墨时用烟胶等掺调的剂型，因亦指墨。\n⑥剂子。指从和好的大块面中分出来的小块。\n⑦量词。多用于指称药物。\n⑧见\"劑鋼\"。\n⑨古代买卖所用的契据，长券叫质，短券叫剂。\n⑩谓决定买卖。\n⑾古代狱讼的要辞。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-剂"},{"id":"glyph-seal-5243","script":"seal","character":"剃","reading":"tì","description":"tì：用刀刮去毛发～头。～刀。～度（佛教指给要出家的人剃去头发，使成为僧尼）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-剃"},{"id":"glyph-seal-524a","script":"seal","character":"削","reading":"xuē；xiāo","description":"xiāo：(1)用刀切去或割去～皮。～发（fà）。刮～。～足适履（把脚削去一块来适应小鞋，喻迁就或勉强凑合）。\n(2)减少，删除～剔。～职。～损。\n(3)像刀削过似的，一般形容陡峭或消瘦～壁。～立（陡峭壁立）。瘦～。\n(4)古代用来书写的刀～刀。\nxuē：义同（一），用于一些复合词～除。～减。～弱。剥～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-削"},{"id":"glyph-seal-524c","script":"seal","character":"剌","reading":"là；lá","description":"là：违背常情、事理乖～。～谬。～戾。\nlá：同拉2”①。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-剌"},{"id":"glyph-seal-524d","script":"seal","character":"前","reading":"qián","description":"qián：(1)指空间，人面所向的一面；房屋等正门所向的一面；家具等靠外的一面，与后”相对～面。～边。～方。面～。～进。～程。\n(2)指时间，过去的，往日的，与后”相对以～。～人。～此。～科。～嫌。～言。～车之鉴。\n(3)顺序在先的～五名。\n(4)向前行进勇往直～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-前"},{"id":"glyph-seal-5251","script":"seal","character":"剑","reading":"jiàn","description":"剑术\n以剑杀人","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-剑"},{"id":"glyph-seal-5254","script":"seal","character":"剔","reading":"tī","description":"tī：(1)分解骨肉，把肉从骨头上刮下来把骨头上的肉～干净。\n(2)从缝隙或孔洞里往外挑拨东西～牙。\n(3)把不好的挑出来～除。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-剔"},{"id":"glyph-seal-5256","script":"seal","character":"剖","reading":"pōu","description":"pōu：(1)破开～开。解～。～面。～腹。\n(2)分析，分辩～白。～解。～析。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-剖"},{"id":"glyph-seal-525c","script":"seal","character":"剜","reading":"wān","description":"wān：挖削～肉补疮（喻只顾眼前，用有害的方法来急救）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-剜"},{"id":"glyph-seal-525e","script":"seal","character":"剞","reading":"jī","description":"jī：〔～劂〕a.雕刻用的曲刀；b.雕版，刻书。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-剞"},{"id":"glyph-seal-5261","script":"seal","character":"剡","reading":"yǎn；shàn","description":"yǎn：(1)尖，锐利曾枝～棘”。\n(2)削，刮～木为楫。\nshàn：〔～溪〕水名，在中国浙江省。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-剡"},{"id":"glyph-seal-5265","script":"seal","character":"剥","reading":"bāo；bō","description":"bāo：去掉外面的皮或其他东西～皮。～花生。\nbō：义同（一），用于复合词～夺。～削（xuē）。～落。～蚀。生吞活～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-剥"},{"id":"glyph-seal-5267","script":"seal","character":"剧","reading":"jù；jv","description":"繁多;繁忙\n⒈极，猛烈，厉害～变。～烈。～疼。\n⒉指戏剧。一种文艺形式，依照剧本，由演员扮演角色，当众演出演～。歌～。川～。独幕～。\n⒊复杂，繁难事～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-剧"},{"id":"glyph-seal-5269","script":"seal","character":"剩","reading":"shèng","description":"shèng：多余，余留下来的～余。～菜。～货。～勇（余勇，如宜将～～追穷寇”）。～水残山。所～无几。就～他一个人。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-剩"},{"id":"glyph-seal-526a","script":"seal","character":"剪","reading":"jiǎn","description":"jiǎn：(1)一种铰东西的用具～刀。\n(2)像剪子的东西火～。夹～。～床。\n(3)用剪子铰～断。～开。～影。～报。～纸。～裁。\n(4)除掉～除。～灭。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-剪"},{"id":"glyph-seal-526f","script":"seal","character":"副","reading":"fù；pì","description":"fù：(1)第二位的，辅助的，区别于正”、主”～职。～手。～官。～使。\n(2)附带的，次要的～业。～品。～食。～刊。～歌。～产品。～作用。\n(3)相配，相称（chèn）名实相～。其实难～。\n(4)量词（a.一组或一套，如一～手套”，全～武装”；b.指态度，如一～笑脸”）。\n正；\npì：剖开，裂开不坼不～”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-副"},{"id":"glyph-seal-5272","script":"seal","character":"割","reading":"gē","description":"gē：(1)切断，截下，划分出来～让。～地。～弃。～舍。～除。～断。～裂。～据。交～。～鸡焉用牛刀（喻做小事情不值得费大力气）。\n(2)灾害天降～于我家。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-割"},{"id":"glyph-seal-527d","script":"seal","character":"剽","reading":"piāo","description":"piāo：(1)抢劫，掠夺～掠。～窃。～袭。～贼。\n(2)轻捷～悍。～轻。～疾。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-剽"},{"id":"glyph-seal-5288","script":"seal","character":"劈","reading":"pī；pǐ","description":"pī：(1)用刀斧或强力破开～杀。～刺。～成两半。\n(2)雷电击坏或击毙天打雷～。\n(3)冲着，正对着～头盖脑。\n(4)两个斜面合成的纵截面呈三角形的简单机械，刀、斧、楔子等各种切削工具的刃都属于这一类（亦称尖劈”）。\npǐ：(1)分开～柴。～成三股。\n(2)分裂，使从原物上分开把菜帮儿～下来。\n(3)腿或手指等过分叉开～叉。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-劈"},{"id":"glyph-seal-5293","script":"seal","character":"劓","reading":"yì","description":"yì：(1)古代割掉鼻子的一种酷刑。\n(2)割除。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-劓"},{"id":"glyph-seal-529b","script":"seal","character":"力","reading":"lì","description":"lì：(1)人和动物筋肉的效能～气。～量。\n(2)一切事物的效能视～。生产～。控制～。\n(3)物理学上指物体之间相互作用，引起运动加速或形变～学。作用～。保守～。\n(4)用极大的力量尽～。～挫。～挽狂澜。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-力"},{"id":"glyph-seal-529d","script":"seal","character":"劝","reading":"quàn","description":"太公劝其女功。\n⒈讲明事理，使人听从～说。～解。～告。～阻。\n⒉勉励，奖励～勉。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-劝"},{"id":"glyph-seal-529e","script":"seal","character":"办","reading":"bàn","description":"做,干\n创设,经营,管理\n准备,操办\n惩罚\n君信可人,必能办贼\n①办理；处理～公、～案。\n②创建；经营～学、～企业。\n③采购；置备～酒席。\n④惩治首恶必～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-办"},{"id":"glyph-seal-529f","script":"seal","character":"功","reading":"gōng","description":"gōng：(1)劳绩，成绩，与过”相对～勋。～绩。论～行赏。徒劳无～。～德无量（liàng）。～成不居（立了功而不把功劳归于自己）。\n(2)成就，成效成～。～能。～亏一篑。事半～倍。急～近利。\n(3)物理学上指用力使物体移动的工作，等于力乘移动的距离～率。\n(4)本领，能耐～夫。～底。～力（a.功夫和力量；b.功效）。～到自然成。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-功"},{"id":"glyph-seal-52a0","script":"seal","character":"加","reading":"jiā","description":"jiā：(1)增多增～。追～。～倍。～封。\n(2)把本来没有的添上去～注解。～冕。\n(3)把几个数合起来的算法～法。\n(4)施以某种动作～以。不～考虑。\n(5)使程度增高～工。～强。～剧。\n(6)超过～人一等（形容学问才能超过常人）。\n(7)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-加"},{"id":"glyph-seal-52a1","script":"seal","character":"务","reading":"wù","description":"操劳\n谋求\n追求\n⒈致力，从事～工。～农。\n⒉事情事～。业～。任～。公～。\n⒊必须，一定～必。除恶～尽。\n⒋追求好高～远。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-务"},{"id":"glyph-seal-52a2","script":"seal","character":"劢","reading":"mài","description":"努力,尽力","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-劢"},{"id":"glyph-seal-52a3","script":"seal","character":"劣","reading":"liè","description":"liè：(1)恶，坏恶～。～迹。\n(2)低下，弱下～势。～等。低～。优～。\n(3)小于一定标准的～弧（小于半圆的弧）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-劣"},{"id":"glyph-seal-52a8","script":"seal","character":"动","reading":"dòng","description":"摇动,震动,移动。与静”相对\n风移影动。╠","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-动"},{"id":"glyph-seal-52a9","script":"seal","character":"助","reading":"zhù；chú","description":"zhù：(1)帮助协同，辅佐辅～。帮～。～手。～人为乐。～桀为虐。拔苗～长（zhǎng）。爱莫能～。\n(2)相传为殷代的租赋制度。\n帮；\nchú：古同锄”，除去。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-助"},{"id":"glyph-seal-52ab","script":"seal","character":"劫","reading":"jié","description":"jié：(1)强取，掠夺～掠。洗～。～道。～富济贫。\n(2)威逼，胁制～持（要挟，挟持）。～制。\n(3)灾难～数（shù）（佛教指注定的灾难）。～难（nàn）∑～（大灾难）。遭～。～后余生。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-劫"},{"id":"glyph-seal-52ac","script":"seal","character":"劬","reading":"qú","description":"qú：(1)过分劳苦，勤劳～劳（指父母养育子女的劳苦）。～～。～录（勤劳，亦作劬禄”）。\n(2)慰劳食（sì）子者三年而出，见于公宫，则～”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-劬"},{"id":"glyph-seal-52ad","script":"seal","character":"劭","reading":"shào","description":"shào：(1)劝勉，自强老而益～。\n(2)美好，高尚年高德～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-劭"},{"id":"glyph-seal-52b2","script":"seal","character":"劲","reading":"jìn","description":"力量,力气\n精神;情绪\n神情;态度\n趣味;兴趣\n指某种程度,限度\n⒈正直，挺拔，坚强有力～士。～松。～草。良将～旅。\n⒉见jiny。\n⒈力气，力量使～。用～。〈引〉\n①精神、情绪、兴趣等干～。闯～。有～头。\n②指属性的程度你尝尝这个香～儿。这菜有点辣～儿。\n⒉见jìng。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-劲"},{"id":"glyph-seal-52b3","script":"seal","character":"劳","reading":"láo","description":"烦劳;麻烦\n慰劳\n⒈人类创造物质或精神财富的活动～力。～心。～动。按～计酬。\n⒉费力，辛苦～而无功。～苦功高。任～任怨。〈引〉劳累，疲劳以逸待～。\n⒋使用言词、实物等慰问～军。慰～。\n⒌功勋～绩。功～。\n劳liáo 1.广阔。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-劳"},{"id":"glyph-seal-52bc","script":"seal","character":"劼","reading":"jié","description":"⒈谨慎。\n⒉牢固。\n⒊勤勉。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-劼"},{"id":"glyph-seal-52be","script":"seal","character":"劾","reading":"hé","description":"hé：揭发罪状弹（tán）～。参（cān）～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-劾"},{"id":"glyph-seal-52bf","script":"seal","character":"势","reading":"shì","description":"力量;威力\n⒈力量，权力，威力～力。有权有～。人多～众。\n⒉力量的趋向～头。趋～。来～凶猛。\n⒊自然界的情况、样子地～。山～。\n⒋政治、军事、社会等方面的情况时～。局～。大～所趋。～均力敌。～在必行。\n⒌姿态，动作姿～。手～。装腔作～。\n⒍男人或雄性动物的生殖器去～。割其～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-势"},{"id":"glyph-seal-52c3","script":"seal","character":"勃","reading":"bó；bèi","description":"bó：(1)突然，忽然～然（a.突然，如～～大怒”；b.兴起的样子，如～～作色”）。\n(2)变色的样子～腾腾（怒气上冲的样子）。\n(3)旺盛，兴起～起。～发。～蓬。\nbèi：古同悖”，违背事理，惑乱糊涂。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-勃"},{"id":"glyph-seal-52c7","script":"seal","character":"勇","reading":"yǒng","description":"yǒng：(1)有胆量，敢做～敢。～毅。～气。～士。英～。奋～。\n(2)中国清代称战争时期临时招募的兵士兵～。劲～。募～。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-勇"},{"id":"glyph-seal-52c9","script":"seal","character":"勉","reading":"miǎn","description":"miǎn：(1)力量不够而尽力做～力。～强（qiǎng）。～为其难。\n(2)劝人努力，鼓励～励。～勖。～慰。自～。互～。\n(3)努力勤～。奋～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-勉"},{"id":"glyph-seal-52cb","script":"seal","character":"勋","reading":"xūn","description":"功劳，尤指较大的功绩，如功勋、勋章。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-52d2","script":"seal","character":"勒","reading":"lè；lēi","description":"lè：(1)套在牲畜上带帽子的笼头马～。\n(2)收住缰绳不使前进悬崖～马。\n(3)强制～令。～索。\n(4)统率～兵。\n(5)雕刻～石。～碑。～铭。\nlēi：(1)用绳子等捆住和套住，然后用力拉紧～紧。\n(2)方言，强制，逼迫。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-勒"},{"id":"glyph-seal-52d6","script":"seal","character":"勖","reading":"xù","description":"xù：古同勉励～勉。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-勖"},{"id":"glyph-seal-52d8","script":"seal","character":"勘","reading":"kān","description":"kān：(1)校对，复看核定～核。～正。～误。校～。\n(2)实现调查，探测～测。～探。～查。\n(3)审问囚犯～问。推～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-勘"},{"id":"glyph-seal-52df","script":"seal","character":"募","reading":"mù","description":"mù：广泛征求招～。～集。～捐。～款。～兵。征～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-募"},{"id":"glyph-seal-52e4","script":"seal","character":"勤","reading":"qín","description":"qín：(1)做事尽力，不偷懒～劳。～快。～奋。～政（勤奋于政事）。～谨。～勉。～恳。克～克俭。\n(2)经常～密（频繁）。来往很～。\n(3)上班，事务～务。～杂。出～◇～。\n(4)担心，忧虑～恤（忧虑怜惜）。\n(5)帮助～王。\n(6)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-勤"},{"id":"glyph-seal-52f0","script":"seal","character":"勰","reading":"xié","description":"xié：同协”（多用于人名）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-勰"},{"id":"glyph-seal-52fa","script":"seal","character":"勺","reading":"sháo","description":"sháo：(1)一种有柄的可以舀取东西的器具～子。饭～儿。掌～儿的（厨师）。\n(2)中国市制容量单位，一升的百分之一。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-勺"},{"id":"glyph-seal-52ff","script":"seal","character":"勿","reading":"wù","description":"wù：副词，不，不要请～动手。～谓言之不预（不要说没有预先说过）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-勿"},{"id":"glyph-seal-5300","script":"seal","character":"匀","reading":"yún","description":"yún：(1)平均，使平均均～。～称（chèn）。\n(2)抽出一部给别人或做别用～兑（让一部分给别人）。～摊。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-匀"},{"id":"glyph-seal-5305","script":"seal","character":"包","reading":"bāo","description":"bāo：(1)用纸、布或其他薄片把东西裹起来～装。～饺子。\n(2)包好了的东西邮～。背（bèi）～。\n(3)装东西的袋书～。皮～。\n(4)容纳在内，总括在一起～括。～举（总括）。～容。～涵。～罗万象。无所不～。\n(5)总揽，负全责～销。～揽。\n(6)保证～赔。～在我身上。\n(7)约定的，专用的～饭。～工。\n(8)围～围。～剿。\n(9)一种带馅的蒸熟的面食～子。糖～儿。\n(10)身体上肿起的疙瘩脓～。\n(11)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-包"},{"id":"glyph-seal-5306","script":"seal","character":"匆","reading":"cōng","description":"cōng：急促～忙。～促。～猝（亦作匆卒”）。～遽。行色～～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-匆"},{"id":"glyph-seal-5308","script":"seal","character":"匈","reading":"xiōng","description":"xiōng：古同胸”。\n〔～奴〕中国古代北方的民族。亦称胡”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-匈"},{"id":"glyph-seal-530d","script":"seal","character":"匍","reading":"pú","description":"pú：〔～匐〕a.爬，手足并行，如～～前进”；b.竭力，如凡民有丧，～～救之”；c.趴，如有些植物的茎～～在地面上”。均亦作匍伏”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-匍"},{"id":"glyph-seal-530f","script":"seal","character":"匏","reading":"páo","description":"páo：中国古代八音之一，如笙、竽等。\n〔～瓜〕a.一年生草本植物。果实比葫芦大，对半剖开可做水瓢。b.这种植物的果实。均俗称瓢葫芦”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-匏"},{"id":"glyph-seal-5310","script":"seal","character":"匐","reading":"fú","description":"fú：〔匍～〕见匍”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-匐"},{"id":"glyph-seal-5315","script":"seal","character":"匕","reading":"bǐ","description":"bǐ：古代指勺、匙之类的取食用具先主方食，失～箸”。\n〔～首〕短剑。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-匕"},{"id":"glyph-seal-5316","script":"seal","character":"化","reading":"huà；huā","description":"huà：(1)性质或形态改变变～。分～。僵～。教（jiào）～。熔～。融～。潜移默～。～干弋为玉帛。。\n(2)佛教、道教徒募集财物～缘。～斋。\n(3)用在名词或形容词后，表示转变成某种性质或状态丑～。绿～。\n(4)习俗，风气有伤风～。\n(5)特指化学”～工。～纤。～肥。\nhuā：同花”⑩。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-化"},{"id":"glyph-seal-5317","script":"seal","character":"北","reading":"běi；bèi","description":"běi：(1)方向，早晨面对太阳，左手的一边，与南”相对～方。～辰（古书指北极星）。～上（古代以北为上，后指去本地以北的某地，与南下”相对）。～极星（出现在天空北部的一颗亮星，人常靠它辨别方向）。～国（指中国北部）。\n(2)打了败仗往回逃败～。\n南；\nbèi：古同背”，违背，违反。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-北"},{"id":"glyph-seal-5319","script":"seal","character":"匙","reading":"shi；chí","description":"chí：舀汤用的小勺子（亦称调（tiáo）羹”）汤～。茶～。\nshi：〔钥～〕开锁的东西。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-匙"},{"id":"glyph-seal-531c","script":"seal","character":"匜","reading":"yí","description":"古代盥洗时用来浇水的器具，有流、有柄。","enabled":true,"collection":"篆字扩展","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-531d","script":"seal","character":"匝","reading":"zā","description":"zā：(1)周，绕一圈绕树三～。\n(2)环绕，满～月。柳荫～地。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-匝"},{"id":"glyph-seal-5320","script":"seal","character":"匠","reading":"jiàng","description":"jiàng：(1)有手艺的人～人。木～。画～。能工巧～。\n(2)灵巧，巧妙独具～心。\n(3)具有某一方面熟练技能，但平庸板滞，缺乏独到之处～气。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-匠"},{"id":"glyph-seal-5321","script":"seal","character":"匡","reading":"kuāng","description":"kuāng：(1)纠正；～正。～谬。\n(2)救～救。～复。～时济世。\n(3)辅助，帮助～助。～扶。～我不逮（帮助我所做不到的）。\n(4)粗略计算，估计，预料～算。～计。\n(5)古同筐”。\n(6)姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-匡"},{"id":"glyph-seal-5323","script":"seal","character":"匣","reading":"xiá","description":"xiá：收藏东西的器具，通常指小型的，盖可以开合～子。木～。梳头～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-匣"},{"id":"glyph-seal-5326","script":"seal","character":"匦","reading":"guǐ","description":"藏于匦中\n匦guǐ匣子，箱子钱～。首饰～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-匦"},{"id":"glyph-seal-532a","script":"seal","character":"匪","reading":"fěi","description":"fěi：(1)强盗，抢劫财物的坏人～徒。～首。叛～。\n(2)不，不是～夷所思（不是常人的想法）。获益～浅。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-匪"},{"id":"glyph-seal-532e","script":"seal","character":"匮","reading":"kuì","description":"运装土的畚。通篑”\n缺乏,空乏\n财匮少而山泽不辟矣。\n通潰”\n⒈缺乏，不足～乏。\n⒉〈古〉通\"篑\"。盛土的竹筐。\n⒊〈古〉通\"柜\"。柜子。\n匮guì 1.大型藏物器。 2.引申指供军事用的蓄水池﹑水库。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-匮"},{"id":"glyph-seal-5339","script":"seal","character":"匹","reading":"pǐ","description":"pǐ：(1)量词（ａ．指整卷的绸或布；ｂ．指马、骡等）。\n(2)单独～夫（ａ．一个人，泛指平常人，如国家兴亡，～～有责”；ｂ．指无学识、无智谋的人，如～～之勇”）。\n(3)相当，相敌，比得上～敌。～配。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-匹"},{"id":"glyph-seal-533a","script":"seal","character":"区","reading":"qū；ou","description":"一种中国古代容器。又用为容量单位\n古代农民播种时所开的穴或沟称为区”\n姓氏\n隐匿\n区别\n⒈姓。\n⒈分别～分。～别。\n⒉划分的地域工业～。居民～。\n⒊行政领域自治～。市辖～。\n区gōu 1.弯曲。\n区kòu 1.见\"区靪\"。\n区qiū 1.见\"区盖\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-区"},{"id":"glyph-seal-533b","script":"seal","character":"医","reading":"yī","description":"⒈治病～疗。～治。\n⒉治病的人～师。良～。兽～。\n⒊增进健康，防治疾病的科学～学。学～。中～学。\n医yì 1.古时盛弓弩矢的器具。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-医"},{"id":"glyph-seal-533f","script":"seal","character":"匿","reading":"nì","description":"nì：隐藏，躲藏隐～。藏～。～名。销声～迹。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-匿"},{"id":"glyph-seal-5341","script":"seal","character":"十","reading":"shí","description":"shí：(1)数名，九加一（在钞票和单据上常用大写拾”代）。\n(2)表示多、久～室九空。\n(3)表示达到顶点～足。～成。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-十"},{"id":"glyph-seal-5343","script":"seal","character":"千","reading":"qiān","description":"千 〈形〉\n比喻数甚大;许许多多\n⒈数目十个百为一～。\n⒉〈表〉众多，极大～军万马。～辛万苦。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-千"},{"id":"glyph-seal-5345","script":"seal","character":"卅","reading":"sà","description":"sà：三十。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-卅"},{"id":"glyph-seal-5347","script":"seal","character":"升","reading":"shēng","description":"shēng：(1)容量单位。\n(2)量粮食的器具。\n(3)向上，高起，提高～力（亦称举力”）。～格。～华（ａ．固态物质直接变为气；ｂ．喻事物的提高和精炼）。～迁。～值。～堂入室（喻人的学问造诣由浅入深，循序渐进，达到精深）。晋～。提～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-升"},{"id":"glyph-seal-5348","script":"seal","character":"午","reading":"wǔ","description":"wǔ：(1)地支的第七位，属马。\n(2)用于计时～时（白天十一点到一点）。～间。～饭。～睡。～休。～夜（半夜、子夜）。\n(3)古同忤”、迕”，逆，背。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-午"},{"id":"glyph-seal-5349","script":"seal","character":"卉","reading":"huì","description":"huì：(1)草的总称奇花异～。\n(2)花奇～怪草。\n(3)姓氏。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-卉"},{"id":"glyph-seal-534a","script":"seal","character":"半","reading":"bàn","description":"bàn：(1)二分之一～圆。～百（五十，多指岁数）。\n(2)不完全的多～。～岛。～透明。～脱产。\n(3)在中间～空。～路上。～夜。\n(4)喻很少一星～点。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-半"},{"id":"glyph-seal-534e","script":"seal","character":"华","reading":"huá","description":"华丽;光彩美丽\n豪华\n称美之词。通常用于跟对方有关的事物\n⒈中华民族或中国的简称～夏。～裔。～侨。～南。驻～使馆。\n⒉美丽～丽。〈引〉精美精～。物～天宝。\n⒊文才才～清英。\n⒋光彩～服。光～。〈引〉显贵，显耀荣～富贵。\n⒌奢侈浮～。\n⒍兴旺繁～。\n⒉华山，又称\"太华山\"，五岳中的西岳，在陕西省～山天下险。智取～山。\n华kuā 1.见\"华离\"","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-华"},{"id":"glyph-seal-534f","script":"seal","character":"协","reading":"xié","description":"与彼协心。\n协规同力。\n合;共同\n尔无共怒\n⒈和恰，共同合作～调。～议。～作。\n⒉从旁相助～助。～理。～办。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-协"},{"id":"glyph-seal-5351","script":"seal","character":"卑","reading":"bēi","description":"bēi：(1)低下，低劣～鄙。～下。～劣。～微。～怯。～恭。地势～湿。～以自牧（保持谦虚的态度以提高自己的修养）。\n(2)古同俾”，使。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-卑"},{"id":"glyph-seal-5352","script":"seal","character":"卒","reading":"zú；cù","description":"zú：(1)兵士～。小～。兵～。\n(2)旧称差役走～。\n(3)死亡病～。生～年月。\n(4)完毕，终了～岁（度过一年）。～业（毕业）。\n(5)终于～胜敌军。\n兵；殁；亡；\n生；\ncù：同猝”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-卒"},{"id":"glyph-seal-5353","script":"seal","character":"卓","reading":"zhuó","description":"zhuó：(1)超高，超，不平凡～见。～然。～越。～著。～绝。～异。\n(2)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-卓"},{"id":"glyph-seal-5355","script":"seal","character":"单","reading":"dān；shàn；chán","description":"dān：一个，独自，简单。shàn：姓氏。chán：用于单于，古代匈奴君主的称号。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-5356","script":"seal","character":"卖","reading":"mài","description":"是一字,后以其声异,故从‘出’以别之。”\n⒈用东西换货币，跟\"买\"相反～粮。～棉。～鸡蛋。\n⒉背叛，出卖～国贼。～身投靠。\n⒊尽量使出～力。～劲。\n⒋故意显示自己、表现自己～弄。～乖。倚老～老。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-卖"},{"id":"glyph-seal-5357","script":"seal","character":"南","reading":"nán；nā","description":"nán：(1)方向，早晨面对太阳，右手的一边，与北”相对～北。～方。～面。～国（指中国南部）。～陲（南部边疆）。～极。～半球。\n(2)姓。\n北；\nnā：〔～无（mó）〕佛教用语，意思是合掌稽首，表示对佛尊敬或皈依，常加于佛、菩萨名的前面，如～～阿弥陀佛”、～～观世音菩萨”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-南"},{"id":"glyph-seal-535a","script":"seal","character":"博","reading":"bó","description":"bó：(1)多，广，大广～。渊～。～学（学问广博）。～览。～爱。～物。\n(2)知道得多～古。\n(3)用自己的行动获得～取。～得。聊～一笑。\n(4)古代的一种棋戏；后泛指赌财物～奕。赌～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-博"},{"id":"glyph-seal-535c","script":"seal","character":"卜","reading":"bo；bǔ","description":"bǔ：(1)古人迷信，用火灼龟甲，以为看了那灼开的裂纹就可以推测出行事的吉凶。\n(2)预料，估计，猜测预～。\n(3)选择（处所）～宅。～邻。\n（蕁）\nbo：〔萝～〕见萝”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-卜"},{"id":"glyph-seal-535f","script":"seal","character":"卟","reading":"bǔ","description":"bǔ：〔～吩〕一种有机化合物，是叶绿素，血红蛋白等的重要组成部分。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-卟"},{"id":"glyph-seal-5360","script":"seal","character":"占","reading":"zhàn；zhān","description":"zhān：(1)迷信的人用铜钱或牙牌等判断吉凶～卜。～卦。\n(2)姓。\nzhàn：(1)据有，用强力取得～据。霸～。强～。\n(2)处于某种地位或情势～理。～优势。\n(3)口说，口授。\n(4)估计上报令民得以律～租。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-占"},{"id":"glyph-seal-5362","script":"seal","character":"卢","reading":"lú","description":"通庐”。房屋\n瞳人\n通颅”。头盖骨\n黑色\n卢奴城内西北隅有水,渊而不流,…水色正黑,俗","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-卢"},{"id":"glyph-seal-5364","script":"seal","character":"卤","reading":"lǔ","description":"天然生成的盐称为卤”。泛指食盐\n卤素\n⒈制盐时剩下的汁液盐～，味苦有毒，可供制豆腐用。\n⒉用酱油、香料、盐水等腌或煮～鸡。～鸭。\n⒊浓汁茶～。鱼～。\n⒋通\"鲁\"。笨，愚钝。\n⒌通\"橹\"。大盾牌。\n⒍通\"掳\"。掠夺。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-卤"},{"id":"glyph-seal-5366","script":"seal","character":"卦","reading":"guà","description":"guà：古代用来占卜的符号八～。占～。变～（借指已定的事情又改动）。～辞。～义。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-卦"},{"id":"glyph-seal-5367","script":"seal","character":"卧","reading":"wò","description":"wò：(1)睡倒，躺或趴～倒。～铺。～室。～底（埋伏下来做内应，如～～传中”）。～槽。～龙（喻隐居或尚未露头角的杰出人才）。～薪尝胆（形容刻苦自励，志图恢复）。藏龙～虎（喻潜藏着人才）。\n(2)把去壳的鸡蛋放到开水里煮～个鸡子儿。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-卧"},{"id":"glyph-seal-536b","script":"seal","character":"卫","reading":"wèi","description":"防护使之不受危险\n⒈保护，防护～国。保～。自～。防～。\n⒉防护人员～兵。警～◇～。\n⒊〈古〉指驴家人捉双～来。\n⒋明代军队编制名。也指驻军的地点，后来沿用为地名～所。天津～。\n⒌周代诸侯国名，在今河北省南部和河南省北部一带。\n①围绕行星运行的天体。\n②\"人造地球卫星\"的简称。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-卫"},{"id":"glyph-seal-536e","script":"seal","character":"卮","reading":"zhī","description":"zhī：(1)古代盛酒的器皿～言（卮不灌酒就空仰着，灌满酒就倾斜，没有一成不变的常态，如同说话没有主见或定见◇常用为对自己著作的谦辞，如《诸子～～》）\n(2)古同栀”，栀子。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-卮"},{"id":"glyph-seal-536f","script":"seal","character":"卯","reading":"mǎo","description":"mǎo：(1)地支的第四位，属兔。\n(2)用于记时～时（早晨五点至七点）。～正（早晨六点）。点～。画～。\n(3)器物接榫的地方凹入的部分～眼。～榫。\n(4)期限比～（中国清代催征钱粮，分期追比）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-卯"},{"id":"glyph-seal-5370","script":"seal","character":"印","reading":"yìn","description":"yìn：(1)图章，戳记～章。～玺。～记。～把子（亦喻政权）。\n(2)痕迹手～。指～。～子（ａ.痕迹；ｂ．高利贷的一种，全称～～钱”）。\n(3)用油墨、染料之类把文字或图画留在纸、布、器皿等材料上～刷。排～。～制。～发（fā）。\n(4)彼此符合～证。心心相～。\n(5)外界事物反映在脑中所留下的形象～象。\n(6)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-印"},{"id":"glyph-seal-5371","script":"seal","character":"危","reading":"wēi","description":"wēi：(1)不安全～险。～殆。～言（ａ．故意说吓人的话；ｂ．直言）。～难（nàn）。～如累（lěi）卵。\n(2)损害～害。～及。\n(3)高的，陡的～石。～樯。\n(4)使人惊奇的～言耸听。\n(5)端正的，正直的正襟～坐。邦有道，～言～行”。\n(6)指人临死病～。垂～。\n(7)星名，二十八宿之一。\n(8)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-危"},{"id":"glyph-seal-5373","script":"seal","character":"即","reading":"jí","description":"jí：(1)就是知识～力量。\n(2)当时或当地～日。～刻。～席。～景。在～。～兴（xìng）。\n(3)就，便黎明～起。\n(4)假如，倘若～使。～便（biàn）。～或。～令。\n(5)靠近不～不离。\n(6)到，开始从事～位。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-即"},{"id":"glyph-seal-5374","script":"seal","character":"却","reading":"què","description":"què：(1)退～步（因畏惧或厌恶而后退，如望而～～”）。退～。\n(2)退还，不受盛情难～。\n(3)表示转折我来了，他～走了。\n(4)去掉失～。了（liǎo）～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-却"},{"id":"glyph-seal-5375","script":"seal","character":"卵","reading":"luǎn","description":"luǎn：(1)动植物的雌性生殖细胞～子。～巢。\n(2)特指动物的蛋～生。～石。～翼（喻养育或庇护）。\n(3)昆虫学上特指受精卵，是动物发育的第一阶段。\n(4)男子睾丸的俗称。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-卵"},{"id":"glyph-seal-5377","script":"seal","character":"卷","reading":"juàn","description":"juàn：(1)可以舒展和弯转成圆筒形的书画长～。画～。手～。\n(2)书籍的册本或篇章上～。第一～。藏书十万～。～帙（书卷成束，用布裹或布囊装起来称帙”，即书套。现一般指书籍）。\n(3)考试用的纸试～。\n(4)机关里分类汇存的档案、文件案～。\n舒；\n（捲）\njuǎn：(1)把东西弯转裹成圆筒形～尺。～帘子。\n(2)裹挟带动～入。～扬。\n(3)弯转裹成筒形的东西烟～儿。纸～儿。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-卷"},{"id":"glyph-seal-5378","script":"seal","character":"卸","reading":"xiè","description":"xiè：(1)把东西去掉或拿下来～车。～装（演员除去化装时穿戴涂抹的东西）。～妆（妇女除去身上的装饰）。拆～。\n(2)解除，不肯承担～任。～肩（卸去肩上的负担，喻卸掉责任）。推～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-卸"},{"id":"glyph-seal-537f","script":"seal","character":"卿","reading":"qīng","description":"qīng：(1)古代高级官名三公九～。～相。\n(2)古代对人敬称，如称荀子为荀卿”。\n(3)自中国唐代开始，君主称臣民。\n(4)古代上级称下级、长辈称晚辈。\n(5)古代夫妻互称～～。～～我我（形容男女间非常亲昵）。\n(6)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-卿"},{"id":"glyph-seal-5382","script":"seal","character":"厂","reading":"chǎng；ān；hàn","description":"ān：同庵”，多用于人名。\nhàn：山边岩石突出覆盖处，人可居住的地方。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-厂"},{"id":"glyph-seal-5384","script":"seal","character":"厄","reading":"è","description":"è：(1)困苦、灾难～运。～境。\n(2)阻塞阻～。\n(3)险要的地方险～。\n(4)木节。\n(5)没有肉的骨头。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-厄"},{"id":"glyph-seal-5386","script":"seal","character":"历","reading":"lì","description":"⒋曆、\n⒈经过经～。～尽千辛万苦。\n⒉经过了的～史。～代。～年。～届。\n⒊遍，逐个，～览。～记。\n⒋指历法，推算年、月、日和节气的方法阳～。农～。也指记载年、月、日和节气等的书、表、册页～书。年～。画～。挂～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-历"},{"id":"glyph-seal-5389","script":"seal","character":"厉","reading":"lì","description":"段注旱石者,刚于柔石者也。字亦作厲、作祕。”朱骏声曰精者曰厎,粗者曰厉『书地理志,述禹贡砥厉砮丹;诗公刘,取厉取锻,礼内则,刀砺;西山经,苕水其中多砥厉;\n中山经,阴山多砺石。”\n祸患;危险\n恶鬼\n疠,瘟疫,传染病\n盗贼\n⒈\"砺\"的本字。磨刀石泰山若～。〈引〉磨，磨练～兵秣马。以～其气。\n⒉严，严肃严～。声色俱～。\n⒊严格，切实～行节约。\n⒋勉励以～三军。\n⒌很，凶猛，猛烈～害。雷～风行。\n⒍祸患，桅降此大～\n厉lài 1.生癞疮;癞疮。 2.指生癞病的人。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-厉"},{"id":"glyph-seal-538b","script":"seal","character":"压","reading":"yā","description":"从上往下增加重力,加压\n压抑,压制;逼迫\n⒈从上面向下使力～住。～紧。～平。～烂。\n⒉搁置不动处理积～物资。\n⒊抑制～抑。～制。\n⒋超过，胜过～过。～倒一切。\n⒌用强力制服～服。欺～。镇～。\n⒍堵塞～塞。\n⒎缩挤～缩。挤～。\n⒏迫近，逼近重兵～境。\n⒐赌博时的下注。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-压"},{"id":"glyph-seal-538c","script":"seal","character":"厌","reading":"yàn；ya","description":"一物压在另一物上\n泛指压制;抑制\n以迷信的方法,镇服或驱避可能出现的灾祸,或致灾祸于人\n⒈憎恶，烦腻～恶。～烦。～倦。讨～。〈引〉嫌山不～高，海不～深。\n⒉饱，满足，也作\"餍\"贪婪无～\n厌yā 1.一物压在另一物上。 2.指被压。 3.指被压死。 4.覆压。 5.压制;抑制。 6.以迷信的方法，镇服或驱避可能出现的灾祸，或致灾祸于人。 7.镇压。 8.堵\n塞。 9.迫近。 10.着;佩带。 11.压降;降低。 12.收缩。 13.承当。\n厌yǎn 1.\"魇\"的古字。恶梦。 2.\"黡\"的古字。掩蔽;掩藏。 3.通\"奄\"■然。参见\"厌的\"。\n厌yān 1.安然。 2.和悦。参见\"厌然\"。 3.微弱;不振。 4.疲倦;困倦。 5.见\"厌厌\"。\n厌yì 1.长揖。 2.见\"厌浥\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-厌"},{"id":"glyph-seal-5395","script":"seal","character":"厕","reading":"cè","description":"假借为侧”。旁边\n①厕所。专供人们大小便的处所公～、男～。\n【厕足其间】插足到那里边。指参与了某件事。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-厕"},{"id":"glyph-seal-5398","script":"seal","character":"厘","reading":"lí","description":"lí：(1)小数名，百分之一～米。\n(2)单位名（ａ．长度单位，中国一市尺的千分之一；ｂ．重量单位，中国一市两的千分之一；ｃ．地积单位，中国一市亩的百分之一；ｄ．利率单位，年利一厘按百分之一计，月利一厘按千分之一计）。\n(3)治理，整理～正（订正）。～革（调整改革）。\n(4)古同嫠”，寡妇。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-厘"},{"id":"glyph-seal-539a","script":"seal","character":"厚","reading":"hòu","description":"hòu：(1)扁平物体上下两个面的距离～度。～薄（厚度）。\n(2)扁平物体上下两个面距离较大的，与薄”相对～纸。～重（zhòng）（ａ．又厚又重；ｂ．丰厚；ｃ．厚道而庄重）。\n(3)深，重（zhòng），浓，多～望。\n(4)不刻薄，待人好～道（诚恳，宽容，道”读轻声）。宽～。\n(5)重视，推崇～此薄彼。\n(6)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-厚"},{"id":"glyph-seal-539d","script":"seal","character":"厝","reading":"cuò","description":"cuò：(1)安置～火积薪。\n(2)停柩，把棺材停放待葬，或浅埋以待改葬浮～。暂～。\n(3)磨刀石。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-厝"},{"id":"glyph-seal-539f","script":"seal","character":"原","reading":"yuán","description":"yuán：(1)最初的，开始的～本。～告。～稿。～籍。～理。～料。～色。～始。～著。\n(2)本来～样。～型。～址。～主。\n(3)谅解，宽容～宥。～谅。\n(4)宽广平坦的地方～野。平～。\n(5)同塬”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-原"},{"id":"glyph-seal-53a2","script":"seal","character":"厢","reading":"xiāng","description":"xiāng：(1)在正房前面两旁的房屋东～房。西～房。\n(2)边，方面这～。\n(3)靠近城的地区城～。关～。\n(4)戏院或影院里特别隔开的座位包～。\n(5)车里容纳人或货的地方车～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-厢"},{"id":"glyph-seal-53a5","script":"seal","character":"厥","reading":"jué","description":"jué：(1)气闭，昏倒昏～。痰～。\n(2)其他的，那个的～父。～后。\n(3)乃，于是左丘失明，～有《国语》”。\n(4)古同撅”，掘。\n(5)古同撅”，断木。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-厥"},{"id":"glyph-seal-53a6","script":"seal","character":"厦","reading":"shà；xià","description":"shà：(1)大屋子广～。高楼大～。\n(2)房子后面的突出的部分前廊后～。\nxià：〔～门〕地名，在中国福建省。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-厦"},{"id":"glyph-seal-53a8","script":"seal","character":"厨","reading":"chú","description":"chú：做饭菜的场所～房。庖～（厨房）。～师。～子。名～。～娘。～具。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-厨"},{"id":"glyph-seal-53a9","script":"seal","character":"厩","reading":"jiù","description":"jiù：马棚，泛指牲口棚马～。～肥。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-厩"},{"id":"glyph-seal-53bb","script":"seal","character":"去","reading":"qù","description":"qù：(1)离开所在的地方到别处；由自己一方到另一方，与来”相对～处。～路。～国。\n(2)距离，差别相～不远。\n(3)已过的，特指刚过去的一年～年。～冬今春。\n(4)除掉，减掉～掉。～皮。～势（ａ．阉割；ｂ．动作或事情终了时的气势）。\n(5)扮演戏曲中的角色他～男主角。\n(6)用在动词后，表示趋向上～。进～。\n(7)用在动词后，表示持续信步走～。\n(8)汉语四声之一～声（ａ．古汉语四声的第三声；ｂ．普通话字调中的第四声）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-去"},{"id":"glyph-seal-53bf","script":"seal","character":"县","reading":"xiàn","description":"县假借为寰”,为州县的县\n官府\n⒈省、市、自治区领导下的一级行政区域。\n⒉〈古〉通\"悬\"。\n县xuán 1.挂。 2.古称悬挂的乐器，如钟磬等。 3.悬钟磬之具。 4.维系;拴系;系联。 5.差距;远。 6.揭示;颁立。 7.悬赏。 8.秤锤。 9.称量;衡量。 10.祭","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-县"},{"id":"glyph-seal-53c1","script":"seal","character":"叁","reading":"sān","description":"sān：三”的大写。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-叁"},{"id":"glyph-seal-53c2","script":"seal","character":"参","reading":"cān","description":"加入\n领悟;琢磨\n检验","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-参"},{"id":"glyph-seal-53c8","script":"seal","character":"又","reading":"yòu","description":"yòu：(1)表示重复或继续，指相同的今天～下雨了。\n(2)表示加重语气、更进一层你～不是小孩！\n(3)表示几种情况或几种性质同时存在～高～大。\n(4)再加上，还有～及。十～五年。\n(5)表示转折这个人挺面熟，一下子～想不起来他叫什么。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-又"},{"id":"glyph-seal-53c9","script":"seal","character":"叉","reading":"chā；chá；chǎ","description":"chā：(1)交错～腰。\n(2)一头分歧便于扎取的器具～子。\nchá：挡住，堵塞住，互相卡住一辆车～在路口。\nchǎ：分开张开～开两腿。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-叉"},{"id":"glyph-seal-53ca","script":"seal","character":"及","reading":"jí","description":"jí：(1)从后头跟上来得～。赶不～。\n(2)达到～格。～第（古代科举考试中选，特指考取进士）。普～。过犹不～。\n(3)趁着，乘～时。～早。～锋而试。\n(4)连词，和，跟阳光、空气～水是生物生存的基本条件。以～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-及"},{"id":"glyph-seal-53cb","script":"seal","character":"友","reading":"yǒu","description":"yǒu：(1)彼此有交情的人朋～。～谊。～情。\n(2)有亲近和睦关系的～邦。～邻。\n(3)相好，互相亲爱～爱。～善。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-友"},{"id":"glyph-seal-53cc","script":"seal","character":"双","reading":"shuāng","description":"禽鸟二只\n云南等地少数民族计算田亩的单位\n成双的,一对\n⒉偶，与\"单\"相对～号。～日。\n⒊加倍的～料。\n⒋匹敌举世无～。\n⒌量词。指成对的一～绣花鞋。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-双"},{"id":"glyph-seal-53cd","script":"seal","character":"反","reading":"fǎn","description":"fǎn：(1)翻转，颠倒～手（ａ．翻过手，手到背后；ｂ．反掌）。～复。～侧。\n(2)翻转的，颠倒的，与正”相对正～两方面的经验。～间（利用敌人的间谍，使敌人内部自相矛盾）。～诉。～馈。适得其～。物极必～。\n(3)抵制，背叛，抗拒～霸。\n(4)和原来的不同，和预感的不同～常。\n(5)回击，回过头来～驳。～攻。～诘。～思。～躬自问。\n(6)类推举一～三。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-反"},{"id":"glyph-seal-53d1","script":"seal","character":"发","reading":"fā；fà","description":"fā：发出，发生，出发；发展。fà：头发。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-53d4","script":"seal","character":"叔","reading":"shū","description":"shū：(1)兄弟排行次序第三伯、仲、～、季。\n(2)父亲的弟弟，亦称跟父亲同辈而年纪较小的男子～父。大～。\n(3)丈夫的弟弟小～子。～嫂。\n(4)拾九月～苴”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-叔"},{"id":"glyph-seal-53d6","script":"seal","character":"取","reading":"qǔ","description":"qǔ：(1)拿索～。～书。～款。窃～。\n(2)选择选～。～材。～景。～道。～样。\n(3)采用采～。听～。吸～。可～。～精用弘。\n(4)得到，招致获～。～经。～偿。～悦。\n(5)消去～消。～缔。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-取"},{"id":"glyph-seal-53d7","script":"seal","character":"受","reading":"shòu","description":"shòu：(1)接纳别人给的东西接～。感～。～精。～权。～托。～降。～益。～业（ａ．跟随老师学习；ｂ．学生对老师自称）。～教。～领。～聘。～理。\n(2)忍耐某种遭遇忍～。～苦。～制。～窘。～累（受到劳累）。\n(3)遭到遭～。～害。～挫。～屈。～辱。～阻。\n(4)适合，中～吃。～看。～听。～使。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-受"},{"id":"glyph-seal-53d8","script":"seal","character":"变","reading":"biàn","description":"性质、状态或情况发生改变；变化；变更。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-53d9","script":"seal","character":"叙","reading":"xù","description":"xù：(1)述说～说。～事。～话。～亲。～旧。\n(2)同序”①②③。\n(3)评议等级次第～功。～奖。～用（分级进用）。～擢（分级提拔，授予宜职）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-叙"},{"id":"glyph-seal-53db","script":"seal","character":"叛","reading":"pàn","description":"pàn：违背自己所属方面的利益投到敌对方面去背～。～国。～逃。～徒。～逆。～变。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-叛"},{"id":"glyph-seal-53df","script":"seal","character":"叟","reading":"sǒu","description":"sǒu：年老的男人老～。童～无欺。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-叟"},{"id":"glyph-seal-53e0","script":"seal","character":"叠","reading":"dié","description":"dié：(1)重复，累积重（chóng）～。层见～出。～罗汉。～韵。～嶂。～翠。\n(2)摺摺～。铺床～被。\n(3)乐曲的重复演奏阳关三～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-叠"},{"id":"glyph-seal-53e3","script":"seal","character":"口","reading":"kǒu","description":"kǒu：(1)人和动物吃东西和发声的器官（亦称嘴”）～腔。～才。～齿。～若悬河。\n(2)容器通外面的地方瓶子～。\n(3)出入通过的地方门～。港～。\n(4)特指中国长城的某些关口（多用作地名）古北～。喜峰～。\n(5)破裂的地方～子。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-口"},{"id":"glyph-seal-53e4","script":"seal","character":"古","reading":"gǔ","description":"gǔ：(1)时代久远的，过去的，与今”相对～代。～稀（人七十岁的代称，源于杜甫《曲江》人生七十古来稀”）。～典。～风。～训。～道（ａ．指古代的道理；ｂ．古朴；ｃ．古老的道路）。\n(2)古体诗的简称五～（五言古诗）。七～（七言古诗）。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-古"},{"id":"glyph-seal-53e5","script":"seal","character":"句","reading":"jù；gōu","description":"jù：(1)由词组成的能表示出一个完整意思的话～子。～法。\n(2)量词，用于语言三～话不离本行（háng）。\n〔～读（dòu）〕古代称文词停顿的地方为句”或读”。\ngōu：〔高～骊〕古国名，即高丽”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-句"},{"id":"glyph-seal-53e8","script":"seal","character":"叨","reading":"dāo；tāo","description":"tāo：(1)承受～光。～拢（谢人款待的话）。～陪。\n(2)古同饕”，贪。\ndāo：〔～～〕话多（后一个叨”读轻声）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-叨"},{"id":"glyph-seal-53ea","script":"seal","character":"只","reading":"zhī","description":"用于计量鸡、禽、牛、羊、球、手、足等的数目。如两只手;三只鸡\n引申为凡物之单者曰只。单一\n⒈仅仅～见树木，不见森林。\n①尽管。\n②〈表〉专一不变。\n①但是。\n②就是～是不说。\n③仅仅是～是有点不同的意见。\n⒈量词两～手。三～鸭。四～杯子。\n只qí 1.见\"只衼\"。 2.通\"痮\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-只"},{"id":"glyph-seal-53eb","script":"seal","character":"叫","reading":"jiào","description":"jiào：呼喊～喊。～嚣（呼喊，吵闹）。～阵。～座（戏曲或演员能吸引观众，看的人多）。～苦不迭。鸣冤～屈。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-叫"},{"id":"glyph-seal-53ec","script":"seal","character":"召","reading":"zhào；shào","description":"zhào：(1)召唤～集。～见。\n(2)召致，引来～祸。～人怨。\nshào：古通邵”，古邑名，在今中国陕西省岐山县西南。（三）姓氏。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-召"},{"id":"glyph-seal-53ef","script":"seal","character":"可","reading":"kě；kè","description":"kě：(1)允许许～。认～。宁～。\n(2)能够～见。～能。～以。不～思议。\n(3)值得，认为～怜。～悲。～亲。～观。～贵。～歌～泣。\n(4)适合～身。～口。～体。\n(5)尽，满～劲儿干。\n(6)大约年～二十。潭中鱼～百许头”。\n(7)表示转折，与可是”、但”相同。\n(8)表示强调他～好了。\n(9)用在反问句里加强反问语气都这么说，～谁见过呢？\n(10)用在疑问句里加强疑问语气这件事他～同意？\n(11)姓。\n否；\nkè：〔～汗（hán）〕中国古代鲜卑、突厥、回纥、蒙古等族君主的称号。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-可"},{"id":"glyph-seal-53f0","script":"seal","character":"台","reading":"tái；tāi","description":"tāi：〔天～〕ａ．山名，在中国浙江省；ｂ．地名，在中国浙江省。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-台"},{"id":"glyph-seal-53f1","script":"seal","character":"叱","reading":"chì","description":"chì：大声呵斥怒～。～问。～骂。～责。～咤（发怒的声音）。～咤风云（形容声势威力很大）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-叱"},{"id":"glyph-seal-53f2","script":"seal","character":"史","reading":"shǐ","description":"shǐ：(1)自然界和人类社会的发展过程，亦指记述、研究这些的文字和学科历～。通～。断代～。近代～。世界～。文学～。～诗。～部（古代图书分类的一大部类，包括各类历史著作）。～坛。～评。～前（没有书面记录的远古）。～不绝书。\n(2)古代掌管记载史事的官太～。内～。\n(3)古代官职刺～。御～。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-史"},{"id":"glyph-seal-53f3","script":"seal","character":"右","reading":"yòu","description":"yòu：(1)面向南时，西的一边，与左”相对～手。～边。\n(2)地理上指西方山～。江～。\n(3)指政治思想上保守或反动的～倾。～派。～翼。\n(4)古代称等级高的～族。～职。无出其～（没有高过它的）。\n(5)崇尚，重视窃以～文兴化，乃致治之所先”。\n(6)古同侑”，劝酒，劝食。\n(7)古同佑”，帮助，偏袒。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-右"},{"id":"glyph-seal-53f5","script":"seal","character":"叵","reading":"pǒ","description":"pǒ：不可～耐。居心～测。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-叵"},{"id":"glyph-seal-53f6","script":"seal","character":"叶","reading":"yè；xié","description":"xié：和洽，合～韵。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-叶"},{"id":"glyph-seal-53f7","script":"seal","character":"号","reading":"hào","description":"哭而有言\n⒈名称称～。年～。牌～。\n⒉商店商～。分～。\n⒊人的名和字以外的别称别～。\n⒋标志记～。符～。信～。加减～。\n⒌排定次序，标上记号排坐～。编～码。将这些东西～上。\n⒍物品的规格、等级特大～。中～。均码～。\n⒎命令～令。发～施令。\n⒏军队或乐队中所用的喇叭～兵。军～队。吹冲锋～。\n⒈大声呼叫～叫◆～。北风怒～。\n⒉大声哭哀～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-号"},{"id":"glyph-seal-53f8","script":"seal","character":"司","reading":"sī","description":"sī：(1)主管，操作～法。～机。～令。～南（古代用磁石做成的辨别方向的仪器，为现在指南针的始祖）。～空（ａ．古代中央政府中掌管工程的长官；ｂ．复姓）。～徒（ａ．古代中央政府中掌管土地和徒役的长官，后为丞相；ｂ．复姓）。～马（ａ．古代中央政府中掌管军务的长官；ｂ．复姓）。～寇（ａ．古代中央政府中掌管刑狱、纠察的长官；ｂ．复姓）。\n(2)官署名称人事～。\n(3)视察～日月之长短。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-司"},{"id":"glyph-seal-53f9","script":"seal","character":"叹","reading":"tàn","description":"⒉因忧闷悲痛而呼气出声～息。忧～。\n⒊因高兴而发出赞许或赞美的长声～为观止。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-叹"},{"id":"glyph-seal-53fd","script":"seal","character":"叽","reading":"jī","description":"稍微吃一点\n呼吸沆瀣兮餐朝霞,噍咀芝英\n悲叹\n形容鸟声、说话声或各种嘈杂声","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-叽"},{"id":"glyph-seal-5401","script":"seal","character":"吁","reading":"yù；xū","description":"xū：(1)叹息长～短叹。\n(2)叹词，表示惊疑～，是何言欤？\n（籲）\nyù：为某种要求而呼喊呼～。～天（呼天诉苦）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-吁"},{"id":"glyph-seal-5403","script":"seal","character":"吃","reading":"chī","description":"chī：(1)把东西送进口中咽下，或依靠某种事物生活～饭。～药。～斋。\n(2)消灭（多用于军事、棋奕）～掉敌人一个连。\n(3)吸～烟。\n(4)感受～惊。～紧。～一堑，长（zhǎng）一智。\n(5)挨～官司。\n(6)承受，支持～不消。\n(7)船身入水的深度～水深浅。\n(8)被～那厮砍了一刀。\n(9)说话结巴口～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-吃"},{"id":"glyph-seal-5404","script":"seal","character":"各","reading":"gè；gě","description":"gè：每个，彼此不同～别。～得其所。～尽所能。～有千秋。～自为政。\ngě：方言，特别这个人真～。\n〔自～儿（gěr）〕自己，亦作自个儿”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-各"},{"id":"glyph-seal-5408","script":"seal","character":"合","reading":"hé；gě","description":"hé：(1)闭，对拢～眼。～抱。珠连璧～。貌～神离。\n(2)聚集～力。～办。～股。～资。\n(3)不违背，一事物与另一事物相应或相符～格。～法。情投意～。\n(4)应该～该。～当。文章～为时而著，诗歌～为时而作”。\n(5)总共，全～家欢乐。\n(6)计，折算～多少钱。\n(7)中国古代乐谱的记音符号，相当于简谱5”。\n开；分；张；拆；离；\ngě：(1)中国市制容量单位，一升的十分之一。\n(2)旧时量粮食的器具，容量为一合，木或竹制，方形或圆筒形。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-合"},{"id":"glyph-seal-5409","script":"seal","character":"吉","reading":"jí","description":"jí：(1)好，有利的，幸福的，与凶”相对～利。～祥。逢凶化～。～光片羽（喻残存的珍贵的文物）。\n(2)吉利的日子择～。\n(3)善，贤，美～人（善良，有才德的人）。～人天相。\n(4)中国吉林省的简称～剧。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-吉"},{"id":"glyph-seal-540a","script":"seal","character":"吊","reading":"diào","description":"diào：(1)祭奠死者或对遭到丧事的人家、团体给予慰问～丧。～孝。～唁。凭～。\n(2)慰问遭遇不幸的人形影相～。\n(3)悬挂上～（自缢）。～灯。\n(4)把毛皮缀在衣面上～皮袄。\n(5)提取，收回～销执照。\n(6)中国旧时钱币单位，一吊为一千个制钱或值一千个制钱的铜币数量。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-吊"},{"id":"glyph-seal-540c","script":"seal","character":"同","reading":"tóng；tòng","description":"tóng：(1)一样，没有差异；相～。～一（ａ．一致，统一；ｂ．共同的一个或一种）。～侪（同辈）。～庚（同岁）。～年。～胞。～人（ａ．在同一单位工作的人；ｂ．同行业的人）。～仁（同人）。～仇敌忾。～工异曲。～室操戈。情～手足。\n(2)共，在一起（从事）共～。～学。～步。殊途～归。～舟共济。\n(3)和，跟～流合污。\n(4)姓。\n异；\ntòng：〔胡～〕见胡”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-同"},{"id":"glyph-seal-540d","script":"seal","character":"名","reading":"míng","description":"míng：(1)人或事物的称谓～字。～氏。～姓。～义。～分（fèn）。～堂。～落孙山。～存实亡。\n(2)起名字秦氏有好女，自～为罗敷”。\n(3)做某事时用来作依据的称号这些人以办学”为～，行骗钱之实。\n(4)叫出，说出不可～状。\n(5)声誉～誉。～声。～优（ａ．出名的，优良的；ｂ．名伶）。～噪一时。～过其实。\n(6)有声誉的，大家都知道的～人。～士。～师。～将（jiàng）。～医。～著。～流。～言。～胜。～剧。\n(7)占有不～一文。\n(8)量词，用于人三～工人。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-名"},{"id":"glyph-seal-540e","script":"seal","character":"后","reading":"hòu","description":"帝王的妻子\n帝嫡妃曰\n⒈跟\"前\"、\"先\"相对。\n①指位置～院。～方。屋～。\n②指时间。晚些的，未到的日～。～天。～来居上。\n③指次序最～三排。～五名。\n①军事上指担任军需供给、医疗、运输等任务。\n②泛指总务工作。\n⒉后代，子孙～生可畏。她无～。\n⒊君王的妻子皇～。\n⒋上古时称君王夏～。\n后xiàng 1.项。参见\"后?\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-后"},{"id":"glyph-seal-540f","script":"seal","character":"吏","reading":"lì","description":"lì：(1)旧时代的大小官员～治。官～。\n(2)旧指小公务员～员。胥～（地方官府中办理文书的人）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-吏"},{"id":"glyph-seal-5410","script":"seal","character":"吐","reading":"tǔ；tù","description":"tǔ：(1)使东西从口里出来～痰。吞～。～刚茹柔（吐出硬的，吃下软的；喻欺软怕硬）。\n(2)放出，露出高粱～穗。～故纳新。\n(3)说出～话。一～为快。\n吞；纳；咽；\ntù：(1)内脏里的东西从口里涌出呕～。上～下泻。\n(2)把吞没的东西退出来～还不义之财。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-吐"},{"id":"glyph-seal-5411","script":"seal","character":"向","reading":"xiàng","description":"泛指窗户\n方向;方位\n⒈朝着，对着～着。朝～。面～朝阳。\n⒉方位，目标，意志所趋方～。走～。奔～〗～。趋～。志～。\n⒊从前，往昔，从来～日。～来。～无先例。\n⒋接近，将近～明。～夕。\n⒌假如，假使～不出其技。\n⒍偏袒偏～。婆婆疼～小孙女。\n向xiǎng 1.通\"享\"。享有，享受。 2.通\"飨\"。犒赏，赐赏。 3.通\"飨\"。祭献。 4.通\"响\"。回声;声音。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-向"},{"id":"glyph-seal-5415","script":"seal","character":"吕","reading":"lǚ；lv","description":"lǚ：(1)中国古代音乐十二律中的阴律，有六种，总称六吕”。\n(2)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-吕"},{"id":"glyph-seal-541b","script":"seal","character":"君","reading":"jūn","description":"jūn：(1)封建时代指帝王、诸侯等～主。～子（ａ．旧指贵族、统治者及其代言人；ｂ．指品行好的人，如正人～～”）。～王。～上。国～。～权。～临。～侧。\n(2)古代的封号商～。平原～。信陵～。长安～。\n(3)对对方的尊称张～。诸～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-君"},{"id":"glyph-seal-541d","script":"seal","character":"吝","reading":"lìn","description":"lìn：(1)当用的财物舍不得用，过分爱惜～惜。悭～。～啬（小气）。\n(2)耻辱得之不休，不获不～”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-吝"},{"id":"glyph-seal-541e","script":"seal","character":"吞","reading":"tūn","description":"tūn：(1)不嚼或不细嚼而咽入～吐。～咽。～噬。狼～虎咽。气～山河。忍气～声。\n(2)兼并，侵占～没（mò）。～并。～蚀。～占。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-吞"},{"id":"glyph-seal-541f","script":"seal","character":"吟","reading":"yín","description":"yín：(1)唱，声调抑扬地念～咏。～诵。～味（吟咏玩味，体味）。～讽（吟咏讽诵）。\n(2)叹息，痛苦的声音～啸（ａ．悲哀愤慨地长叹；ｂ．吟咏）。呻～。\n(3)．中国古代诗歌的一种名称秦妇～。\n(4)鸣，叫风～。猿～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-吟"},{"id":"glyph-seal-5420","script":"seal","character":"吠","reading":"fèi","description":"fèi：狗叫～叫。狂～。蜀犬～日（喻少见多怪）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-吠"},{"id":"glyph-seal-5426","script":"seal","character":"否","reading":"fǒu；pǐ","description":"fǒu：(1)表示不同意，不认可～定。\n(2)不，用在表示疑问的词句里可～？。\n(3)不如此，不是这样，不然～则。学则正，～则邪。\n可；\npǐ：不好，坏，恶～极泰来（否”和泰”，前者是坏卦，后者是好卦。指事情坏到了极点，就会向好的方向转化）。未知善～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-否"},{"id":"glyph-seal-542b","script":"seal","character":"含","reading":"hán","description":"hán：(1)衔在嘴里，不吐出也不咽下～一口水。～漱剂。～英咀（jǔ）华（喻反复琢磨体味文章的妙处）。～饴弄孙（含着糖逗小孙子，形容老年人的乐趣）。\n(2)藏在里面，包容在里面包～。～义。～量。～苞。～蕴。～混。～垢纳污（指包容坏人坏事）。\n(3)怀有某种感情或意思，不完全表露出来～怒。～羞。～情。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-含"},{"id":"glyph-seal-542c","script":"seal","character":"听","reading":"tīng","description":"听于庭。\n⒈用耳朵接受声音～录音。兼～则明。偏～则暗。\n⒉顺从，接受～话。～从。～指挥。言～计从。\n⒊随，任凭～便。～凭。～之任之。\n⒍等候～回音。～候分派。\n听yǐn 1.笑貌。 2.见\"听听\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-听"},{"id":"glyph-seal-542e","script":"seal","character":"吮","reading":"shǔn","description":"shǔn：聚拢嘴唇吸～吸。～乳。～痈舐痔（喻不择手段谄媚讨好有权势的人）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-吮"},{"id":"glyph-seal-542f","script":"seal","character":"启","reading":"qǐ","description":"经传皆作啟”\n⒈开，打开，开发，开拓～开。～封。～地三千里。\n⒉开导～蒙。～示。～发。\n⒊开始～程。～用。\n⒋陈述，说明～事。～告。敬～者。\n⒌书信书～。小～。\n①开口难于～齿。\n②笑。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-启"},{"id":"glyph-seal-5434","script":"seal","character":"吴","reading":"wú","description":"wú：(1)中国周代诸侯国名，在今江苏省南部和浙江省北部，后扩展至淮河下游一带～钩（古代吴地出产的一种弯刀，后泛指锋利的刀剑）。～越同舟（喻过去的仇人由于当前利害一致而成为朋友）。\n(2)中国东汉末年三国之一～下阿蒙（喻原先学识粗浅的人）。\n(3)泛指中国江苏省南部和浙江省北部一带～语。～牛喘月（喻见到类似事物就胆怯害怕起来）。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-吴"},{"id":"glyph-seal-5438","script":"seal","character":"吸","reading":"xī","description":"xī：(1)从口或鼻把气引入体内呼～。～气。～烟。\n(2)引取～引。～附。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-吸"},{"id":"glyph-seal-5439","script":"seal","character":"吹","reading":"chuī","description":"chuī：(1)合拢嘴唇用力出气～打。～灯（ａ．把灯火吹灭；ｂ．喻人死亡；ｃ．喻失败、垮台）。～毛求疵。～鼓手（ａ．办婚、丧事时吹奏鼓乐的人；ｂ．胡乱吹捧和宣扬别人的人）。～灰之力。\n(2)说大话～牛。～嘘。\n(3)类似吹的动作～拂。风～草动。\n(4)（事情）失败～台。\n(5)消息流传，鼓动宣传鼓～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-吹"},{"id":"glyph-seal-543b","script":"seal","character":"吻","reading":"wěn","description":"wěn：(1)嘴唇～合（意见、看法完全相同）。\n(2)用嘴唇接触表喜爱、亲热接～。～别。\n(3)动物的嘴。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-吻"},{"id":"glyph-seal-543e","script":"seal","character":"吾","reading":"wú；yù","description":"wú：(1)我，我的～身。～国。～辈。\n(2)姓。\nyù：古同御”，抵御。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-吾"},{"id":"glyph-seal-5440","script":"seal","character":"呀","reading":"ya；yā","description":"yā：(1)叹词，表示惊疑～！你流血了。\n(2)象声词，形容摩擦转动的声音两扇大门～的一声打开了。\ny：助词，在句末，啊”受前一字的韵母ａ，ｅ，ｉ，ｏ，收音的影响而发出的变音这朵花～，真鲜艳?郑码jhi，u5440，gbkd1bd","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-呀"},{"id":"glyph-seal-5446","script":"seal","character":"呆","reading":"dāi","description":"dāi：(1)傻，愚蠢～子。～气。～里撒（sā）奸（表面痴呆，暗藏奸诈）。\n(2)不灵活，发愣～板。～滞。～若木鸡（形容因惊恐而发愣）。\n(3)同待2”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-呆"},{"id":"glyph-seal-5448","script":"seal","character":"呈","reading":"chéng","description":"chéng：(1)显出，露出～现。～祥。\n(2)恭敬地送上去～上。～报。面～。\n(3)下级报告上级的文件～文。～子。\n(4)古同程”，规划、法式、标准。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-呈"},{"id":"glyph-seal-544a","script":"seal","character":"告","reading":"gào","description":"gào：(1)说给别人，通知～谕。～知。～诫。～诉。报～。劝～。奔走相～。\n(2)向行政司法机关检举、控诉～发。～状。控～。\n(3)表明，请求～老。～急。自～奋勇。\n(4)宣布或表示某种情况出现～成。～竭（宣布某种东西用尽）。～罄（现指财物用尽或货物等售完）。公～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-告"},{"id":"glyph-seal-5458","script":"seal","character":"员","reading":"yuán","description":"官员的定额。又指官员、官吏\n⒈在工作或学习的人公务～。售货～。演～。学～。\n⒉团体或组织中的分子会～。团～。党～。\n⒋量词。指人数已满～。三～大将。\n⒌〈古〉通\"圆\"。圆形～石。\n员yùn姓。\n员yún见于古人名。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-员"},{"id":"glyph-seal-5466","script":"seal","character":"呦","reading":"yōu","description":"yōu：(1)叹词，表示惊异～，书怎么脏了？\n(2)象声词，鹿叫声，亦形容哭声～～鹿鸣，食野之苹”。\n(3)语气词，相当于啊”你也是个没性气的东西～！”","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-呦"},{"id":"glyph-seal-5468","script":"seal","character":"周","reading":"zhōu","description":"zhōu：(1)圈子，环绕～围。～天。～转（zhuǎn）。～匝（a.环绕；b.周到）。\n(2)普遍、全面～身。～延。～全。～游。\n(3)时期的一轮，亦特指一个星期～岁。～年。～期。～星（十二年）。上～。\n(4)完备～到。～密。～详。～正（端正）。～折（事情进行不顺利）。\n(5)给，接济～济。\n(6)中国朝代名西～。东～。北～◇～。\n(7)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-周"},{"id":"glyph-seal-5471","script":"seal","character":"呱","reading":"guā；gū；guǎ","description":"guā：〔～～〕a.声音响亮；b.形容好，如～～叫”，顶～～”。\ngū：〔～～〕指小儿哭声，如～～坠地”。\nguǎ：〔拉～儿（guǎr）〕方言，聊天，闲谈。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-呱"},{"id":"glyph-seal-5473","script":"seal","character":"味","reading":"wèi","description":"wèi：(1)舌头尝东西所得到的感觉～觉。～道（亦指兴趣）。滋～。\n(2)鼻子闻东西所得到的感觉气～。香～儿。\n(3)情趣趣～。兴～。意～。津津有～。\n(4)体会，研究体～。耐人寻～。\n(5)量词，指中草药的一种五～药。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-味"},{"id":"glyph-seal-5476","script":"seal","character":"呶","reading":"náo","description":"náo：喧哗～～（说话唠叨，含有使人讨厌的意思，如～～不休”）。纷～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-呶"},{"id":"glyph-seal-5477","script":"seal","character":"呷","reading":"gā；xiā","description":"xiā：小口儿地喝～了一口茶。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-呷"},{"id":"glyph-seal-547b","script":"seal","character":"呻","reading":"shēn","description":"shēn：〔～吟〕痛苦时口中发出哼哼的声音，如无病～～”（喻说话作文没有内容）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-呻"},{"id":"glyph-seal-547c","script":"seal","character":"呼","reading":"hū","description":"hū：(1)喊～喊。～声。～吁。～天号（háo）地。\n(2)唤，叫～唤。～叫。～应。～朋引类（招引同类的人，共同做坏事）。\n(3)往外出气，与吸”相对～气。～吸。\n(4)象声词～地跳起来。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-呼"},{"id":"glyph-seal-547d","script":"seal","character":"命","reading":"mìng","description":"mìng：(1)动植物的生活能力生～。救～。逃～。拼～。～脉。性～。相依为～。\n(2)迷信认为生来就注定的贫富、寿数等天～。～相（xiàng）。～运（a.迷信指生死、贫富和一切遭遇；b.喻发展变化的趋向，如人民一定能掌握自己的～～”）。\n(3)上级对下级的指示奉～。遵～。～令。使～。\n(4)给予（名称等）～名。～题。～意。\n(5)指派，使用～官。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-命"},{"id":"glyph-seal-5480","script":"seal","character":"咀","reading":"jǔ；zuǐ；jv","description":"jǔ：含在嘴里细细玩味～嚼（jué）（a.细嚼；b.喻对事物反复体会）‖英～华（喻读书吸取精华）。\nzuǐ：同嘴”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-咀"},{"id":"glyph-seal-5484","script":"seal","character":"咄","reading":"duō","description":"duō：表示呵叱～！你这光棍！那么简单”。\n〔～～〕表示惊怪，如～～怪事。”","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-咄"},{"id":"glyph-seal-5486","script":"seal","character":"咆","reading":"páo","description":"páo：猛兽怒吼熊～龙吟殷岩泉”。～哮（a.猛兽怒吼；b.形容水流的奔腾轰鸣；c.形容人的暴怒喊叫）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-咆"},{"id":"glyph-seal-548c","script":"seal","character":"和","reading":"hé；hè；huó；huò；hú","description":"hé：(1)相安，谐调～美。～睦。～谐。～声。～合（a.和谐；b.古代神话中象征夫妻相爱的两个神）。～衷共济。\n(2)平静温～。祥～。～平。～气。～悦。～煦。惠风～畅。\n(3)平息争端讲～。～约。～议。～亲。\n(4)数学上指加法运算中的得数二加二的～是四。\n(5)连带～盘托出（完全说出来）。～衣而卧。\n(6)连词，跟，同我～老师打球。\n(7)介词，向，对我～老师请教。\n(8)指日本国～服（日本式服装）。～文。大～民族。\n(9)体育比赛不分胜负的结果～棋。～局。\n(10)姓。\n战；\nhè：(1)和谐地跟着唱曲高～寡。\n(2)依照别人的诗词的题材或体裁作诗词～诗。\n战；\nhuó：在粉状物中搅拌或揉弄使粘在一起～面。～泥。\n战；\nhuò：(1)粉状或粒状物搀和在一起，或加水搅拌～药。奶里～点儿糖。～弄。～稀泥。\n(2)量词，指洗衣服换水的次数或一剂药煎的次数衣裳洗了三～水。\n战；\nhú：打麻将或斗纸牌时某一家的牌合乎规定的要求，取得胜利。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-和"},{"id":"glyph-seal-548e","script":"seal","character":"咎","reading":"jiù","description":"jiù：(1)过失，罪过～戾。负～。以彰其～。\n(2)怪罪，处分既往不～。～由自取（遭受责备、惩处或祸害是自己造成的）。\n(3)灾祸休～（吉凶）。\n(4)怨仇与臣有～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-咎"},{"id":"glyph-seal-548f","script":"seal","character":"咏","reading":"yǒng","description":"yǒng：(1)唱，声调有抑扬地念～赞。歌～。吟～。～唱。\n(2)用诗词等来描述，抒发感情～梅。～史。～怀。～叹。～叹调（富于抒情的独唱曲）。\n(3)指诗词佳～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-咏"},{"id":"glyph-seal-5499","script":"seal","character":"咙","reading":"lóng","description":"喉咙,咽部和喉部的统称","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-咙"},{"id":"glyph-seal-54a4","script":"seal","character":"咤","reading":"zhà","description":"zhà：〔叱～〕见叱”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-咤"}];
